import React, { useReducer } from 'react';
import reducerRegistry from '../reducerRegistry';

const initialState = {
  count: 0
};

function counterReducer(state = initialState, action) {

  switch (action.type) {

      case 'INCREMENT':
          return {
              ...state,
              count: state.count + 1
          };

      case 'DECREMENT':
          return {
              ...state,
              count: state.count - 1
          };

      default:
          return state;
  }
}

export default counterReducer;
